content.css:
html,
body {
  margin: 0;
  padding: 0;
  overflow: hidden;
  font-family: "Segoe UI", wf_standard-font, -apple-system, BlinkMacSystemFont, sans-serif;
  -webkit-font-smoothing: antialiased;
}
.cv-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: #8A93A5;
  font-size: 11px;
}
svg .cv-dim {
  opacity: 0.32;
}
svg text.cv-picked {
  fill: #1A2233;
  font-weight: 700;
}
.cv-table {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  color: #1A2233;
  font-variant-numeric: tabular-nums;
}
.cv-head {
  display: grid;
  flex: 0 0 auto;
  height: 24px;
  align-items: end;
  border-bottom: 1px solid #1A2233;
  color: #566175;
  font-weight: 600;
  font-size: 0.92em;
  padding-bottom: 3px;
}
.cv-body {
  flex: 1 1 auto;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
}
.cv-row {
  display: grid;
  align-items: center;
  border-bottom: 1px solid #ECEFF4;
  cursor: pointer;
  box-sizing: border-box;
}
.cv-row:hover {
  background: #F2F5FA;
}
.cv-cell {
  overflow: hidden;
  white-space: nowrap;
  box-sizing: border-box;
  padding: 0 6px;
}
.cv-viz {
  padding: 0;
  line-height: 0;
}
.cv-num {
  text-align: right;
}
.cv-center {
  text-align: center;
}
.cv-label {
  display: flex;
  align-items: center;
  min-width: 0;
}
.cv-label-text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.cv-chevron {
  flex: 0 0 14px;
  color: #8A93A5;
  font-size: 0.85em;
  user-select: none;
}
.cv-chevron:hover {
  color: #3D63DD;
}
.cv-group {
  font-weight: 600;
}
.cv-leaf {
  color: #566175;
}
.cv-ratio {
  color: #8A93A5;
  font-style: italic;
}
.cv-depth-0.cv-group {
  background: #F4F6FA;
}
.cv-depth-1.cv-group {
  color: #1A2233;
}
.cv-result {
  border-top: 1px solid #1A2233;
}
.cv-ac {
  color: #1A2233;
}
.cv-pm {
  color: #566175;
}
.cv-total-col {
  font-weight: 600;
  border-left: 1px solid #DFE4EC;
}
.cv-scenario {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 5px;
}
.cv-mark {
  display: inline-block;
  width: 9px;
  height: 9px;
  box-sizing: border-box;
}
.cv-mark-ac {
  background: #3B4252;
}
.cv-mark-pm {
  border: 1.5px solid #3B4252;
  background: #FFFFFF;
}
.cv-mark-py {
  background: #A9B1BE;
}
.cv-subhead {
  color: #8A93A5;
  font-weight: 400;
}
.cv-row.cv-selected,
.cv-row.cv-selected:hover {
  background: #1A2233;
}
.cv-row.cv-selected .cv-cell,
.cv-row.cv-selected:hover .cv-cell,
.cv-row.cv-selected .cv-chevron,
.cv-row.cv-selected:hover .cv-chevron {
  color: #FFFFFF;
}
.cv-row.cv-selected text:not(.cv-tone),
.cv-row.cv-selected:hover text:not(.cv-tone) {
  fill: #FFFFFF;
}
.cv-row.cv-selected line[stroke-width="1"],
.cv-row.cv-selected:hover line[stroke-width="1"] {
  stroke: rgba(255, 255, 255, 0.55);
}
